namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int CeilingRatePoints = 10;

    public static int DiscountCents(LoyaltyTier tier, int subtotalCents)
    {
        var baseRatePoints = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
        };

        var sizeBonusPoints = subtotalCents switch
        {
            >= 20_000 => 3,
            >= 5_000 => 1,
            _ => 0,
        };

        var effectiveRatePoints = Math.Min(baseRatePoints + sizeBonusPoints, CeilingRatePoints);

        return (subtotalCents * effectiveRatePoints) / 100;
    }
}
EOF
